\section{Introduction}

\subsection{The bound and the question}

Many arguments in geometry, combinatorics and theoretical computer science
share a common core. One decomposes an object into successive layers, tracks a
monotone quantity --- volume, measure, cardinality, entropy, potential --- and
invokes an averaging argument to locate a layer that is cheap. The canonical
instance is: \emph{if a total of $A$ is removed in $N$ steps, some step removes
at most $A/N$}.

This argument locates thin slabs in decompositions of convex bodies, sparse
levels in filtrations, cheap recursion depths in divide-and-conquer schemes,
and good stopping times in iterative geometric constructions. Its virtue is
that it requires nothing of the object being peeled. Precisely for that reason
it says nothing about tightness. Four questions arise.

\begin{itemize}
\item \emph{Sharpness.} Is the constant $1$ optimal, or does monotonicity force
something better?
\item \emph{Rigidity.} If the bound is saturated, what does the peeling look
like?
\item \emph{Stability.} If it is nearly saturated, is the peeling nearly
extremal?
\item \emph{Realisation.} Do the extremal profiles occur as genuine geometric
decompositions?
\end{itemize}

This paper answers all four. In brief: the constant is optimal; the extremisers
are exactly the affine profiles; extremality is \emph{equivalent} to a
transitive symmetry on the layers; the stability estimate is linear; and the
geometric extremisers are the equal-volume dilation peelings of arbitrary
star-shaped bodies, with universal, shape-independent dilation factors.

\subsection{Organisation}

Section~\ref{sec:profiles} sets up peeling profiles and proves the upper bound
with its error control and density refinements. Section~\ref{sec:rigidity}
proves rigidity and its group-theoretic reformulations.
Section~\ref{sec:stability} proves stability. Section~\ref{sec:energy} gives
the variational description. Section~\ref{sec:balls} constructs the geometric
matching family for balls. Section~\ref{sec:concentration} proves boundary
concentration. Section~\ref{sec:universal} removes the ball.
Section~\ref{sec:algorithms} discusses algorithms and applications, and
Section~\ref{sec:future} lists open directions.

\section{Peeling profiles and the upper bound}\label{sec:profiles}

\subsection{Definitions}

\begin{definition}[Peeling profile]
A \emph{peeling profile} is a function $s : \N \to \R$ that is antitone
($s_j \le s_i$ whenever $i \le j$) and nonnegative. We read $s_k$ as the
residual content after $k$ peeling steps.
\end{definition}

\begin{definition}[Layer content, budget, rate]
For a peeling profile $s$ and $k, N \in \N$ set
\[
g_k = s_k - s_{k+1}, \qquad A_N = s_0 - s_N, \qquad \rho_N = A_N/N
\]
(the layer content, the budget of the window $[0,N)$, and the average rate;
$\rho_0 := 0$). Antitonicity gives $g_k \ge 0$, $A_N \ge 0$, $\rho_N \ge 0$.
\end{definition}

\begin{lemma}[Telescoping]\label{lem:telescope}
$\sum_{k=0}^{N-1} g_k = A_N$, and hence $N\rho_N = A_N$ for all $N \in \N$.
\end{lemma}

\begin{proof}
Immediate telescoping of $\sum_{k<N}(s_k - s_{k+1})$; the identity
$N\rho_N = A_N$ is then the definition of $\rho_N$ for $N \ge 1$, and reads
$0 = 0$ for $N=0$.
\end{proof}

Lemma~\ref{lem:telescope} is the only structural input to
Sections~\ref{sec:profiles}--\ref{sec:energy}.

\subsection{The stopping-time bound}

\begin{theorem}[Existence of a good stopping time]\label{thm:stopping}
Let $s$ be a peeling profile and $N \ge 1$. There exists $k < N$ with
$g_k \le \rho_N$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:telescope}, $\sum_{k<N} g_k = A_N = \sum_{k<N} \rho_N$. If
every term of the left sum exceeded $\rho_N$ the sums would compare strictly,
a contradiction; hence some term is at most $\rho_N$.
\end{proof}

\subsection{The affine estimate and its error}

\begin{definition}[Affine estimate]
For $N \ge 1$ set $\ell_k = s_0 - k\rho_N$.
\end{definition}

By Lemma~\ref{lem:telescope}, $\ell_0 = s_0$ and $\ell_N = s_N$: the affine
estimate interpolates the profile at the endpoints of the window.

\begin{lemma}[Error representation]\label{lem:error}
For all $k$,
\[
s_k - \ell_k \;=\; \sum_{j<k}(\rho_N - g_j),
\]
and $\sum_{j<N}(\rho_N - g_j) = 0$; hence for $k \le N$,
$\sum_{j=k}^{N-1}(\rho_N - g_j) = -(s_k - \ell_k)$.
\end{lemma}

\begin{proof}
Expanding, $\sum_{j<k}(\rho_N-g_j) = k\rho_N - (s_0 - s_k) = s_k - \ell_k$. The
full-window sum vanishes by Lemma~\ref{lem:telescope}, and splitting it at $k$
gives the tail form.
\end{proof}

\begin{theorem}[Two-sided error bound]\label{thm:errorbound}
For $0 \le k \le N$, $\;|s_k - \ell_k| \le \max(k, N-k)\,\rho_N$.
\end{theorem}

\begin{proof}
Since $g_j \ge 0$, Lemma~\ref{lem:error} gives
$s_k - \ell_k \le \sum_{j<k}\rho_N = k\rho_N$. Applying the same estimate to
the tail sum, $\sum_{j=k}^{N-1}(\rho_N - g_j) \le (N-k)\rho_N$, and the tail
form of Lemma~\ref{lem:error} gives $s_k - \ell_k \ge -(N-k)\rho_N$. Both
coefficients are at most $\max(k,N-k)$.
\end{proof}

\begin{proposition}[Hypothesis-free error bound]
For $0 \le k \le N$, $\;|s_k - \ell_k| \le A_N$.
\end{proposition}

\begin{proof}
Both $s_k$ and $\ell_k$ lie in $[s_N, s_0]$, an interval of length $A_N$: the
former by antitonicity, the latter because $k\rho_N$ ranges over $[0,A_N]$.
\end{proof}

\subsection{Density of good stopping times}

\begin{theorem}[Markov bound for peelings]\label{thm:markov}
For any $t \in \R$, $\;\#\{k<N : g_k \ge t\}\cdot t \le A_N$.
\end{theorem}

\begin{proof}
With $S = \{k<N: g_k \ge t\}$ we have
$|S|t \le \sum_{k \in S} g_k \le \sum_{k<N} g_k = A_N$, the last step because
the omitted layers are nonnegative.
\end{proof}

\begin{corollary}[Density in units of the rate]
If $N \ge 1$, $A_N > 0$ and $c > 0$, then
$\#\{k<N : g_k \ge c\rho_N\} \le N/c$.
\end{corollary}

Thus at most half of the steps have a layer of at least twice the average, at
most a tenth of at least ten times the average, and so on.

\subsection{Stable windows}

\begin{definition}[Block profile]
For $J \ge 1$ the \emph{block profile of stride $J$} is
$s^{(J)}_k = s_{Jk}$; it is again antitone and nonnegative.
\end{definition}

\begin{theorem}[Stable window]\label{thm:stablewindow}
Let $J \ge 0$ and $M \ge 1$. There is a block index $b < M$ with
\[
g_{Jb+j} \;\le\; \frac{s_0 - s_{JM}}{M} \qquad \text{for every } j<J.
\]
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:stopping} to $s^{(J)}$ over $M$ steps: some $b<M$
satisfies $s_{Jb} - s_{J(b+1)} \le (s_0 - s_{JM})/M$. For $j<J$, antitonicity
gives $s_{Jb+j} \le s_{Jb}$ and $s_{J(b+1)} \le s_{Jb+j+1}$, whence
$g_{Jb+j} \le s_{Jb} - s_{J(b+1)}$.
\end{proof}

One therefore obtains not a single good step but a run of $J$ consecutive good
steps; this is the form in which the bound is usually applied to multiscale
constructions.

\section{Rigidity: equality forces symmetry}\label{sec:rigidity}

\subsection{The four-way equivalence}

\begin{theorem}[Rigidity of the peeling bound]\label{thm:rigidity}
Let $s$ be a peeling profile and $N \ge 1$. The following are equivalent.
\begin{enumerate}
\item $g_k \le \rho_N$ for all $k<N$;
\item $g_k = \rho_N$ for all $k<N$;
\item $s_k = s_0 - k\rho_N$ for all $k \le N$;
\item $g_k = g_{(k+1) \bmod N}$ for all $k<N$.
\end{enumerate}
\end{theorem}

\begin{proof}
$(1)\Rightarrow(2)$: the numbers $\rho_N - g_k$, $k<N$, are nonnegative and sum
to $0$ by Lemma~\ref{lem:telescope}, so each vanishes.
$(2)\Rightarrow(3)$: induction, the step being
$s_{k+1} = s_k - g_k = (s_0 - k\rho_N) - \rho_N$.
$(3)\Rightarrow(1)$: subtracting consecutive instances gives $g_k = \rho_N$.
$(2)\Rightarrow(4)$: both sides equal $\rho_N$, since $(k+1)\bmod N < N$.
$(4)\Rightarrow(2)$: clause (4) says the gap function is invariant under the
cyclic successor map on $\{0,\dots,N-1\}$; iterating from $0$ gives $g_k = g_0$
for all $k<N$, and then $Ng_0 = A_N$ forces $g_0 = \rho_N$.
\end{proof}

\begin{remark}
Clause (4) is the conceptual pivot: extremality is not an analytic condition
but a symmetry condition, verifiable --- or engineerable --- by exhibiting a
group action rather than by estimating anything.
\end{remark}

\subsection{Symmetry implies extremality}

Write $\gamma(i) = g_i$ for the gap function on the window
$\{0,\dots,N-1\}$.

\begin{theorem}[Symmetry forces extremality]\label{thm:symmetry}
Let $N \ge 1$ and let a group $G$ act pretransitively on the window (for all
$i,j$ there is $\sigma \in G$ with $\sigma \cdot i = j$). If
$\gamma(\sigma\cdot i) = \gamma(i)$ for all $\sigma \in G$ and all $i$, then
$\gamma \equiv \rho_N$ and $s_k = s_0 - k\rho_N$ for $k \le N$.
\end{theorem}

\begin{proof}
Pretransitivity and invariance make $\gamma$ constant, $\gamma \equiv
\gamma(0)$. Summing over the window and using Lemma~\ref{lem:telescope} gives
$N\gamma(0) = A_N$. Clause (3) of Theorem~\ref{thm:rigidity} concludes.
\end{proof}

\begin{corollary}[A single $N$-cycle suffices]\label{cor:cycle}
Let $\sigma$ be the successor map $i \mapsto i+1 \bmod N$. Its $m$-th power is
translation by $m$, so $\langle\sigma\rangle$ acts pretransitively; hence
invariance of the layer contents under $\sigma$ alone forces the profile to be
affine on the window.
\end{corollary}

\begin{theorem}[Extremality is maximal symmetry]\label{thm:maxsym}
For $N \ge 1$,
\[
\bigl(g_k \le \rho_N \ \forall k<N\bigr)
\iff
\bigl(\gamma(\sigma\cdot i) = \gamma(i)\ \forall \sigma \in \Sym(N),\ \forall i\bigr).
\]
\end{theorem}

\begin{proof}
($\Rightarrow$) By Theorem~\ref{thm:rigidity} the gap function is the constant
$\rho_N$, invariant under every permutation. ($\Leftarrow$) $\Sym(N)$ acts
pretransitively via transpositions, so Theorem~\ref{thm:symmetry} applies.
\end{proof}

Combining Corollary~\ref{cor:cycle} with Theorem~\ref{thm:maxsym}: invariance
under a single $N$-cycle already implies invariance under the full symmetric
group of the window. There is no intermediate regime.

\section{Stability}\label{sec:stability}

\begin{theorem}[Stability of the peeling bound]\label{thm:stability}
Let $s$ be a peeling profile, $N \ge 1$, $\varepsilon \ge 0$, and suppose
$g_j \le (1+\varepsilon)\rho_N$ for all $j<N$. Then for every $k \le N$,
\[
|s_k - \ell_k| \;\le\; \varepsilon A_N .
\]
\end{theorem}

\begin{proof}
The hypothesis is the one-sided deviation bound
$\rho_N - g_j \ge -\varepsilon\rho_N$ for $j<N$. Summing over $j<k$ and using
Lemma~\ref{lem:error} gives $s_k - \ell_k \ge -k\varepsilon\rho_N \ge
-N\varepsilon\rho_N = -\varepsilon A_N$. Summing over $k \le j < N$ and using
the tail form of Lemma~\ref{lem:error} gives
$-(s_k-\ell_k) \ge -(N-k)\varepsilon\rho_N \ge -\varepsilon A_N$.
\end{proof}

\begin{remark}
The bound is linear in $\varepsilon$, uniform in $k$, and involves no
dependence on $N$ beyond the budget. At $\varepsilon = 0$ it reproduces clause
(3) of Theorem~\ref{thm:rigidity}, so Theorem~\ref{thm:stability} strictly
contains rigidity: the extremal set is quantitatively rigid, with sup-norm
distance to extremality controlled by the multiplicative slack.
\end{remark}

\begin{theorem}[Geometric stability for ball peelings]
Fix $d, N \ge 1$, $R \ge 0$, $\varepsilon \ge 0$. Let $r_0 = R \ge r_1 \ge
\cdots \ge r_N = 0$ be nonnegative radii with
\[
\vol B(0,r_j) - \vol B(0,r_{j+1}) \le (1+\varepsilon)\frac{\vol B(0,R)}{N},
\qquad j<N .
\]
Then for every $k \le N$,
\[
\Bigl|\vol B(0,r_k) - \vol B(0,R)\bigl(1-\tfrac kN\bigr)\Bigr| \le \varepsilon\,\vol B(0,R).
\]
\end{theorem}

\begin{proof}
The volumes $s_k = \vol B(0,r_k)$ form a peeling profile with budget
$\vol B(0,R)$ and rate $\vol B(0,R)/N$; apply Theorem~\ref{thm:stability} and
identify the affine estimate.
\end{proof}

\section{The variational description}\label{sec:energy}

Define the \emph{layer energy} $E_N = \sum_{k<N} g_k^2$.

\begin{theorem}[Energy identity]\label{thm:energyid}
For $N \ge 1$,
\[
E_N - \frac{A_N^2}{N} \;=\; \sum_{k<N}\bigl(g_k - \rho_N\bigr)^2 .
\]
\end{theorem}

\begin{proof}
Expand the right-hand side as $\sum g_k^2 - 2\rho_N\sum g_k + N\rho_N^2$ and
substitute $\sum_{k<N}g_k = A_N$ and $\rho_N = A_N/N$.
\end{proof}

\begin{corollary}\label{cor:energyge}
$E_N \ge A_N^2/N$ for every peeling profile and every $N \ge 1$.
\end{corollary}

This is Cauchy--Schwarz for $(g_0,\dots,g_{N-1})$ against the all-ones vector,
obtained here by completing the square without invoking Cauchy--Schwarz.

\begin{theorem}[Equality case]\label{thm:energyeq}
$E_N = A_N^2/N$ if and only if $g_k = \rho_N$ for all $k<N$, i.e.\ if and only
if the peeling is extremal in the sense of Theorem~\ref{thm:rigidity}.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:energyid} equality means a sum of squares vanishes, hence
every term vanishes.
\end{proof}

Theorem~\ref{thm:energyeq} gives a second, independent proof of rigidity and
reframes the extremisers as minimisers of a quadratic energy; the excess
$E_N - A_N^2/N$ is exactly $N$ times the variance of the layer distribution
and serves as a computable defect functional.

\begin{theorem}[Dual pigeonhole]
For $N \ge 1$ there is also $k<N$ with $g_k \ge \rho_N$; consequently
$\min_{k<N} g_k \le \rho_N \le \max_{k<N} g_k$, with equality throughout
precisely in the extremal case.
\end{theorem}

\section{The geometric matching family: equal-volume shells}\label{sec:balls}

Throughout, $\vol$ is Lebesgue measure on $\R^d$ and $B(0,r)$ the open
Euclidean ball.

\begin{lemma}[Scaling]\label{lem:ballscale}
For $d \ge 1$ and $r \ge 0$, $\vol B(0,r) = r^d \vol B(0,1)$, and
$\vol B(0,1) \in (0,\infty)$. Hence $r \mapsto \vol B(0,r)$ is strictly
increasing on $[0,\infty)$; in particular nonnegative radii with equal ball
volumes are equal.
\end{lemma}

\begin{definition}[Shell radii and shells]
For $R \ge 0$, $d,N \ge 1$, $k \in \N$ set
\[
r_k = R\bigl(\max(0,\,1-\tfrac kN)\bigr)^{1/d}, \qquad
S_k = B(0,r_k) \setminus B(0,r_{k+1}).
\]
Then $r_0 = R$, $r_N = 0$, and $k \mapsto r_k$ is antitone and nonnegative.
\end{definition}

\begin{theorem}[The shell peeling is an equipartition]\label{thm:shells}
For $d,N \ge 1$, $R \ge 0$ and $k \le N$,
\[
\vol B(0,r_k) = \vol B(0,R)\bigl(1-\tfrac kN\bigr),
\]
and for $k<N$, $\;\vol(S_k) = \vol B(0,R)/N$. In particular the profile
$s_k = \vol B(0,r_k)$ is exactly affine and saturates
Theorem~\ref{thm:stopping} at every step.
\end{theorem}

\begin{proof}
The first display is Lemma~\ref{lem:ballscale} applied to $r_k$, whose $d$-th
power is $R^d(1-k/N)$. Subtracting consecutive instances gives the second,
using that the balls are nested and of finite measure so that the measure of
the difference is the difference of the measures.
\end{proof}

\begin{theorem}[$O(d)$-equivariance]
For every linear isometry $e$ of $\R^d$ and every $k$, $e(S_k) = S_k$.
\end{theorem}

\begin{proof}
A linear isometry fixes the origin and preserves norms, so $e(B(0,r)) = B(0,r)$
for every $r$; being injective, $e$ commutes with set difference.
\end{proof}

Hence the layers are $O(d)$-invariant sets of equal volume; their contents are
constant, so invariant under the cyclic shift, and
Corollary~\ref{cor:cycle} recovers extremality by pure symmetry.

\begin{theorem}[Rigidity of ball peelings]\label{thm:ballrigid}
Let $d,N \ge 1$, $R \ge 0$, and let $\rho_0 = R \ge \rho_1 \ge \cdots \ge
\rho_N = 0$ be radii with
\[
\vol B(0,\rho_k) - \vol B(0,\rho_{k+1}) \le \frac{\vol B(0,R)}{N},
\qquad k<N .
\]
Then $\rho_k = R(1-k/N)^{1/d}$ for every $k \le N$.
\end{theorem}

\begin{proof}
The volumes form a peeling profile of budget $\vol B(0,R)$; the hypothesis is
clause (1) of Theorem~\ref{thm:rigidity}, so clause (3) gives
$\vol B(0,\rho_k) = \vol B(0,R)(1-k/N) = \vol B(0,r_k)$. Strict monotonicity of
ball volume in the radius (Lemma~\ref{lem:ballscale}) yields $\rho_k = r_k$.
\end{proof}

Observe the shape of the argument: the volume profile is pinned by arithmetic
alone, and geometry enters only to recover the radius from the volume.

\begin{theorem}[Optimality of the constant]
Let $c<1$ and $R>0$. The equal-volume shell family has every shell of volume
exactly $\vol B(0,R)/N > c\,\vol B(0,R)/N$; hence the constant $1$ in
Theorem~\ref{thm:stopping} cannot be improved, already within the class of
concentric ball peelings in any fixed dimension.
\end{theorem}

\begin{example}\label{ex:disc}
In the plane ($d=2$) with $R=1$, $N=4$ the radii are
$1,\ \sqrt3/2 \approx 0.8660,\ \sqrt2/2 \approx 0.7071,\ 1/2,\ 0$, and each of
the four annuli has area $\pi/4$. The radii are not in arithmetic progression;
only their squares are. This is why rigidity must be phrased through the volume
profile rather than the radius profile, and it is what makes
Theorem~\ref{thm:ballrigid} genuinely dimension-dependent.
\end{example}

\begin{theorem}[Equal-volume shells minimise shell energy]
Let $d,N \ge 1$, $R \ge 0$, and let $\rho_0 = R \ge \cdots \ge \rho_N = 0$ be
any nested radii. Then
\[
\sum_{k<N}\bigl(\vol B(0,\rho_k) - \vol B(0,\rho_{k+1})\bigr)^2
\;\ge\; \frac{(\vol B(0,R))^2}{N},
\]
and the equal-volume radii $r_k = R(1-k/N)^{1/d}$ attain the minimum.
\end{theorem}

\begin{proof}
Corollary~\ref{cor:energyge} applied to the volume profile; attainment is
Theorem~\ref{thm:shells} together with $N(\vol B(0,R)/N)^2 = (\vol
B(0,R))^2/N$.
\end{proof}

\section{Boundary concentration}\label{sec:concentration}

\begin{lemma}[Geometric-sum inequality]\label{lem:geom}
For $d \ge 1$ and $0 \le s \le 1$, $\;(1-s)\,d\,s^{d-1} \le 1 - s^d$.
\end{lemma}

\begin{proof}
Identically $1-s^d = (1-s)\sum_{i<d}s^i$. Since $0 \le s \le 1$, each term
$s^i$ with $i \le d-1$ is at least $s^{d-1}$, so the sum is at least
$d\,s^{d-1}$; multiply by $1-s \ge 0$.
\end{proof}

\begin{lemma}[Normalised concentration]\label{lem:normconc}
For $d \ge 1$ and $N \ge 2$, $\;1 - (1-\tfrac1N)^{1/d} \le \dfrac{1}{d(N-1)}$.
\end{lemma}

\begin{proof}
Put $t = 1 - 1/N \in [0,1]$ and $s = t^{1/d}$, so $s^d = t$ and $s \in [0,1]$.
Lemma~\ref{lem:geom} gives $(1-s)\,d\,s^{d-1} \le 1-t = 1/N$; since
$s^d \le s^{d-1}$ this yields $(1-s)\,d\,t \le 1/N$, i.e.
$(1-s)\,d\,\frac{N-1}{N} \le \frac1N$, which rearranges to
$1-s \le \frac{1}{d(N-1)}$.
\end{proof}

\begin{theorem}[Boundary concentration]\label{thm:conc}
For $d \ge 1$, $N \ge 2$ and $R \ge 0$, the outermost shell of the
equal-volume peeling of $B(0,R) \subseteq \R^d$ has thickness
\[
R - R\Bigl(1-\tfrac1N\Bigr)^{1/d} \;\le\; \frac{R}{d(N-1)} .
\]
\end{theorem}

\begin{proof}
Factor out $R$ and apply Lemma~\ref{lem:normconc}.
\end{proof}

The outermost shell carries a full $1/N$ of the volume yet occupies a radial
band of width $O(R/(dN))$: the discrepancy factor is exactly the dimension.
Numerically, for $d = 10$, $N = 2$, $R = 1$ the true thickness is
$1 - 2^{-1/10} \approx 0.0670$ against the bound $0.1$; for $d = 100$, $N=2$ it
is $\approx 0.0069$ against $0.01$. The bound is within roughly $30\%$ of the
truth and has the correct $1/d$ decay, which is exactly what the factorisation
in Lemma~\ref{lem:geom} captures. This is the quantitative reason equal-volume
ball peelings behave so differently from the flat arithmetic profile they
realise: uniform in volume, they collapse geometrically onto the boundary
sphere.

\section{Universality: arbitrary star-shaped bodies}\label{sec:universal}

The ball is the most symmetric body available, so one might suspect the
extremality of its shell peeling is an artefact of that symmetry. It is not.

\begin{definition}[Star-shaped]
A set $K \subseteq \R^d$ is \emph{star-shaped about the origin} if $x \in K$
and $0 \le t \le 1$ imply $tx \in K$.
\end{definition}

No convexity, smoothness or symmetry is assumed. We take $K$ measurable with
$\vol(K) < \infty$ throughout.

\begin{lemma}[Scaling for arbitrary bodies]\label{lem:bodyscale}
For $c \ge 0$ and measurable $K \subseteq \R^d$, $\vol(cK) = c^d\vol(K)$; if
$\vol(K) < \infty$ then $\vol(cK) < \infty$.
\end{lemma}

\begin{proof}
The scaling law of Haar (Lebesgue) measure on $\R^d$ under the dilation
$x \mapsto cx$, whose Jacobian determinant is $c^d$.
\end{proof}

\begin{lemma}[Nesting of dilates]\label{lem:nesting}
If $K$ is star-shaped about the origin and $0 \le a \le b$, then
$aK \subseteq bK$.
\end{lemma}

\begin{proof}
If $b = 0$ then $a = 0$ and both sides coincide. If $b>0$, take $ay \in aK$
with $y \in K$. Since $0 \le a/b \le 1$, star-shapedness gives $(a/b)y \in K$,
and $ay = b((a/b)y) \in bK$.
\end{proof}

\begin{definition}[Universal dilation factors and layers]
For $d,N \ge 1$ and $k \in \N$ set
\[
c_k = \bigl(\max(0,\,1-\tfrac kN)\bigr)^{1/d}, \qquad
L_k = c_kK \setminus c_{k+1}K .
\]
Then $c_0 = 1$, $c_N = 0$, $k \mapsto c_k$ is antitone and nonnegative, and
crucially $c_k$ depends only on $d$, $N$, $k$ and not at all on $K$.
\end{definition}

\begin{theorem}[Equal measures]\label{thm:bodyequal}
For $d,N \ge 1$, measurable $K$ with $\vol(K)<\infty$, and $k \le N$,
\[
\vol(c_kK) = \vol(K)\bigl(1-\tfrac kN\bigr),
\]
so the associated peeling profile is exactly affine and every layer content is
$\vol(K)/N$. If moreover $K$ is star-shaped about the origin then for $k<N$
\[
\vol(L_k) = \frac{\vol(K)}{N}.
\]
\end{theorem}

\begin{proof}
The first display is Lemma~\ref{lem:bodyscale} with $c = c_k$, since
$c_k^d = 1-k/N$ for $k \le N$. For the second, star-shapedness gives the
nesting $c_{k+1}K \subseteq c_kK$ (Lemma~\ref{lem:nesting}), and both dilates
have finite measure, so the measure of the difference is the difference of the
measures, namely $\vol(K)\bigl((1-\tfrac kN)-(1-\tfrac{k+1}N)\bigr) =
\vol(K)/N$. (When $c_{k+1}=0$ and $K \neq \emptyset$ the dilate degenerates to
$\{0\}$, of measure zero.)
\end{proof}

\begin{theorem}[Universal equivariance]
Let $e$ be a linear isometry of $\R^d$ with $e(K) = K$. Then $e(L_k) = L_k$
for every $k$.
\end{theorem}

\begin{proof}
Linearity gives $e(cK) = c\,e(K) = cK$ for $c \ge 0$; injectivity lets $e$
commute with set difference.
\end{proof}

Thus the entire linear symmetry group of $K$ --- the orthogonal group for a
ball, the dihedral group of order $8$ for a planar square, the trivial group
for a generic body --- acts on the decomposition, preserving each layer
setwise.

\begin{theorem}[Universal rigidity]\label{thm:bodyrigid}
Let $d,N \ge 1$ and let $K$ be measurable with $0 < \vol(K) < \infty$. Let
$1 = \lambda_0 \ge \lambda_1 \ge \cdots \ge \lambda_N = 0$ be nonnegative
dilation factors with
\[
\vol(\lambda_kK) - \vol(\lambda_{k+1}K) \le \frac{\vol(K)}{N}, \qquad k<N .
\]
Then $\lambda_k = c_k = (1-k/N)^{1/d}$ for every $k \le N$.
\end{theorem}

\begin{proof}
The numbers $s_k = \vol(\lambda_kK) = \lambda_k^d\vol(K)$ form a peeling
profile with $s_0 = \vol(K)$, $s_N = 0$, budget $\vol(K)$ and rate
$\vol(K)/N$. The hypothesis is clause (1) of Theorem~\ref{thm:rigidity}, so
clause (3) yields $\lambda_k^d\vol(K) = \vol(K)(1-k/N)$. Cancelling the
positive factor $\vol(K)$ gives $\lambda_k^d = c_k^d$, and $t \mapsto t^d$ is
strictly increasing on $[0,\infty)$, so $\lambda_k = c_k$.
\end{proof}

\begin{theorem}[The matching family, final form]
Let $d,N \ge 1$ and let $K \subseteq \R^d$ be measurable, star-shaped about
the origin, of finite volume. Then:
\begin{enumerate}
\item every layer $L_k$, $k<N$, has volume exactly the peeling rate
$\vol(K)/N$;
\item every linear isometry preserving $K$ preserves each $L_k$;
\item the peeling profile is exactly affine, $s_k = s_0 - k\vol(K)/N$ for
$k \le N$, so the stopping-time bound of Theorem~\ref{thm:stopping} is
saturated at every single step.
\end{enumerate}
\end{theorem}

Consequently the extremisers of the peeling upper bound realised in Euclidean
geometry are parameterised by pairs $(K,G)$ with $K$ a star-shaped body and
$G$ any group of linear symmetries of $K$: the dimension fixes the radial
profile $(1-k/N)^{1/d}$, and the body is otherwise free.

\begin{example}[The square]
Take $d = 2$, $K = [-1,1]^2$ with $\vol(K) = 4$, and $N = 4$. The dilation
factors are $1,\ \sqrt3/2,\ \sqrt2/2,\ 1/2,\ 0$ --- identical to the disc case
of Example~\ref{ex:disc}, as the theory predicts, since the factors depend only
on $d$ and $N$. The four square-annulus layers have areas $1,1,1,1$. The group
acting is the dihedral group of order $8$, not $O(2)$; extremality is
unaffected.
\end{example}

\begin{remark}
The independence of the factors from $K$ is the sharpest form of the message.
The stopping-time bound is a statement about numbers; its geometric extremisers
therefore cannot see anything about a body except its volume and the dimension.
The dilation profile is the unique radial law compatible with the scaling
$\vol(cK) = c^d\vol(K)$ and an equipartition of volume, and that is why it is
universal.
\end{remark}

\section{Algorithms and applications}\label{sec:algorithms}

\subsection{Locating a good stopping time}

Theorem~\ref{thm:stopping} is constructive: scanning $k = 0,\dots,N-1$ and
returning the first index with $g_k \le \rho_N$ costs $O(N)$ evaluations. By
Theorem~\ref{thm:markov} a random index succeeds against the relaxed threshold
$c\rho_N$ with probability at least $1 - 1/c$, so $O(1)$ evaluations suffice
when a constant-factor loss is acceptable. A deterministic shortcut exists in a
common special case.

\begin{theorem}[Monotone peelings need no search]
Suppose the layer contents are nonincreasing, $g_j \le g_i$ whenever $i \le j$.
Then $g_{N-1} \le \rho_N \le g_0$: the last step of the window is always an
admissible stopping time and the first step is never one, unless all gaps
coincide.
\end{theorem}

\begin{proof}
The minimum of $N$ numbers is at most their average and the maximum at least
their average; monotonicity identifies these as $g_{N-1}$ and $g_0$.
\end{proof}

The existential search is therefore needed only for genuinely oscillating
peelings.

\subsection{Constructing an equal-volume decomposition}

Given $d$, $N$ and a star-shaped $K$, Theorem~\ref{thm:bodyequal} provides a
closed-form equipartition: compute $c_k = (1-k/N)^{1/d}$ for $k = 0,\dots,N$
and take $L_k = c_kK \setminus c_{k+1}K$. The cost is $N$ evaluations of a real
power --- no integration, no root-finding, and no dependence on the shape of
$K$. Volume-balanced radial partitioning is a standard primitive in adaptive
mesh refinement, stratified importance sampling, level-of-detail schemes and
balanced nested spatial search structures; the theorem says the optimal strata
are always the same, in closed form, whatever the region.

\subsection{Certifying extremality and measuring the defect}

Two computable certificates arise. The sup-norm defect
$\max_{k \le N}|s_k - \ell_k|$ is bounded by $\varepsilon A_N$ whenever all
layers obey $g_k \le (1+\varepsilon)\rho_N$ (Theorem~\ref{thm:stability}). The
energy defect $E_N - A_N^2/N = \sum_k (g_k - \rho_N)^2$
(Theorem~\ref{thm:energyid}) is exactly $N$ times the variance of the layer
contents, vanishes exactly at extremality, and is smooth --- hence usable as a
loss function when optimising a family of peelings towards equipartition.

\subsection{High-dimensional design guidance}

Theorem~\ref{thm:conc} is a warning label. An algorithm that peels a
high-dimensional ball into equal-volume shells cannot assume those shells are
geometrically thick: their thickness is $O(R/(dN))$. Conversely,
geometrically uniform shells force wildly unequal volumes, since a shell of
thickness $R/N$ near radius $R$ carries about a $d/N$ fraction of the volume.
Volume uniformity and geometric uniformity are incompatible in high dimensions,
and Theorem~\ref{thm:conc} quantifies the trade-off.

\section{Discussion and future directions}\label{sec:future}

The picture is a chain of equivalences attached to a peeling window:
\[
\underbrace{g_k \le \rho_N\ \forall k}_{\text{inequality}}
\iff \underbrace{g_k = \rho_N\ \forall k}_{\text{equipartition}}
\iff \underbrace{\text{transitive symmetry of }\gamma}_{\text{group theory}}
\iff \underbrace{E_N = A_N^2/N}_{\text{variational}},
\]
with the geometric realisation of the common condition being exactly the family
of dilation peelings $c_kK$, $c_k = (1-k/N)^{1/d}$, of star-shaped bodies,
together with their symmetry groups. Stability makes the first equivalence
quantitative; boundary concentration explains why the geometric realisations
look nothing like the flat profiles they realise.

\begin{conjecture}[Rigidity survives the loss of nesting by dilation]
Let $K \subseteq \R^d$ be a convex body containing the origin and let
$K = K_0 \supseteq K_1 \supseteq \cdots \supseteq K_N = \{0\}$ be arbitrary
convex bodies (not assumed to be dilates) with
$\vol(K_k) - \vol(K_{k+1}) \le \vol(K)/N$ for every $k$. Then
$\vol(K_k) = (1-k/N)\vol(K)$ for all $k$, and if in addition each $K_k$ is
homothetic to $K$ the homothety ratios are forced to be $(1-k/N)^{1/d}$.
\end{conjecture}

The rigidity theorem already forces the volume profile with no geometric input;
the remaining work is to recover the shape from the volume, which is where
convexity and Brunn--Minkowski theory should enter. The volume half is
established here, since Theorem~\ref{thm:bodyrigid} derives it for dilation
families.

\begin{conjecture}[The concentration order $1/d$ is exact]
For $d \ge 1$ and $N \ge 2$,
\[
\frac{R}{d(N-1)}\Bigl(1-\frac1N\Bigr) \;\le\;
R - R\Bigl(1-\tfrac1N\Bigr)^{1/d} \;\le\; \frac{R}{d(N-1)},
\]
so Theorem~\ref{thm:conc} is tight up to the factor $1-1/N$, and the shell
decomposition converges, after rescaling by $d$, to the exponential radial
profile $R(1-e^{-t})$.
\end{conjecture}

The factorisation $1-s^d = (1-s)\sum_{i<d}s^i$ used in Lemma~\ref{lem:geom} is
two-sided: bounding $\sum_{i<d}s^i$ above by $d$ instead of below by
$d\,s^{d-1}$ yields the matching lower bound, and the limit statement then
follows from the definition of the exponential.

\begin{conjecture}[Symmetry is necessary, not merely sufficient]
Let $s$ be a peeling profile with $A_N>0$. Then $s$ saturates the
stopping-time bound on the window of length $N$ if and only if there is a group
acting pretransitively on the $N$ steps and leaving the layer contents
invariant; moreover the set of such groups is a full conjugation-closed family
of transitive subgroups of $\Sym(N)$.
\end{conjecture}

Theorem~\ref{thm:maxsym} establishes the equivalence with invariance under the
full symmetric group, and Corollary~\ref{cor:cycle} with invariance under a
single $N$-cycle. What remains is the classification: which transitive
subgroups arise as symmetry groups of the layer structure of a given extremal
peeling, and whether every transitive subgroup is realised by some geometric
extremiser $(K,G)$.

Further questions include the continuous analogue (replacing the window by a
measure on $[0,T]$, where the energy identity becomes a variance
decomposition), the correct replacement for the layer decomposition when $K$ is
not star-shaped so the dilates are no longer nested, and anisotropic scalings
in which scalar dilation is replaced by a one-parameter subgroup of linear maps
of determinant $1-k/N$, turning the rigidity question into one about
determinant flows in $SL_d(\R)$.

